CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 VARCHAR2, arg4 VARCHAR2) AS
BEGIN
    -- Step 1: For drivers older than arg1, set driver name to arg2
    UPDATE "driver"
       SET "Name" = arg2
     WHERE "Age" > arg1;

    -- Step 2: Bump years worked by 1 on school_bus records for drivers older than arg1
    UPDATE "school_bus"
       SET "Years_Working" = "Years_Working" + 1
     WHERE "Driver_ID" IN (SELECT "Driver_ID" FROM "driver" WHERE "Age" > arg1);

    -- Step 3: If arg3 isn't null and driver party matches it, set school_bus if_full_time to 'T'
    IF arg3 IS NOT NULL THEN
        UPDATE "school_bus"
           SET "If_full_time" = 'T'
         WHERE "Driver_ID" IN (SELECT "Driver_ID" FROM "driver" WHERE "Age" > arg1 AND "Party" = arg3);
    END IF;

    -- Step 4: Delete drivers with null party
    DELETE FROM "driver"
     WHERE "Party" IS NULL;

    -- Step 5: Set home city to arg4 for remaining drivers
    UPDATE "driver"
       SET "Home_city" = arg4;

    -- Step 6: If arg3 isn't null, set party to arg3 for remaining drivers older than arg1
    IF arg3 IS NOT NULL THEN
        UPDATE "driver"
           SET "Party" = arg3
         WHERE "Age" > arg1;

        -- Step 7: Set if_full_time to 'F' on school_bus records for remaining drivers with party = arg3 and age <= arg1
        UPDATE "school_bus"
           SET "If_full_time" = 'F'
         WHERE "Driver_ID" IN (SELECT "Driver_ID" FROM "driver" WHERE "Party" = arg3 AND "Age" <= arg1);
    END IF;
END;

